"""Author a separate holdout before any v21 parent or candidate inference."""
import json
from pathlib import Path
R=Path(__file__).resolve().parent
prior=[json.loads(s) for s in (R.parent/'requirements-draft-v20/acquisition.jsonl').read_text().splitlines()]
systems={t:next(x['messages'][0]['content'] for x in prior if x['task']==t) for t in ['draft','bounds']}
rows=[]
def add(key,turns,desc,title,questions=None,literals=None):
    assert len(turns)==9,key
    m=[{'role':'system','content':systems['draft']}]+[{'role':'user' if i%2==0 else 'assistant','content':s} for i,s in enumerate(turns)]
    m.append({'role':'assistant','content':json.dumps({'summary':title,'description':desc,'questions':questions or []},ensure_ascii=False)})
    row={'id':'fresh-'+key,'task':'draft','messages':m}
    if literals:row['required_literals']=literals
    rows.append(row)
add('cancel-first',['Для формы решили заменить in_mark на out_mark, а host_mark на guest_mark.','С чего начнём?','Сначала поправка: in_mark оставляем как есть.','А второе решение?','Оно в силе.','Возвращать host_mark?','Нет, замена на guest_mark согласована.','Записать обе правки?','Запиши итог с учётом отмены первой.'],'В форме сохранить in_mark без замены на out_mark. Использовать guest_mark вместо host_mark.','Поля формы')
add('cancel-second',['План: source_no меняется на result_no, а box_no — на shelf_no.','Оба изменения нужны?','Стоп, последнее из них убираем из плана.','Первое тоже вычеркнуть?','Я отменил только последнее.','Значит, box_no остаётся?','Да.','Что записать?','Действующие поля и какую замену не выполнять.'],'Использовать result_no вместо source_no. Сохранить box_no, не заменять его на shelf_no.','Согласованные поля')
