add('unchanged-field-send',['Справку нотариусу пока не отправлять. В ней номер дела и дата.','Вместо номера дела использовать номер заявления?','Эту идею отклоняю.','Запрет отправки остаётся?','Теперь снимаю его, нотариусу можно отправить.','Разрешение означает и согласие на новое поле?','Нет, это разные решения.','Какой итог?','Запиши справку с прежними реквизитами и новым разрешением.'],'Сохранить номер дела и дату в справке, номер заявления вместо номера дела не использовать. Нотариусу отправка разрешена, прежний запрет снят.','Справка нотариусу')
add('copy-scope',['Подготовим одинаковые выписки для экономиста и ревизора, пока без пересылки.','Экономисту можно переслать?','Да.','Ревизору тоже?','Нет, разрешение только для экономиста.','Ревизору дописать комментарий?','Выписки должны быть одинаковыми, комментария не нужно.','Подвести итог?','Да, отдельно укажи содержимое и разрешения.'],'Подготовить одинаковые выписки без дополнительного комментария. Экономисту пересылка разрешена, ревизору не пересылать.','Две выписки')
add('undo-ban',['Список экспонатов смотрителю не передавать, в нём инвентарный номер и зал.','Что изменилось?','Запрет отменён, передачу разрешаю.','Зал убрать?','Нельзя, оба реквизита нужны.','Вернуть запрет?','Нет, это уже устаревшее решение.','Что фиксируем?','Разрешённую передачу с обоими реквизитами.'],'Передача списка экспонатов смотрителю разрешена. Сохранить инвентарный номер и зал. Прежний запрет не восстанавливать.','Список экспонатов')
add('add-not-replace',['Есть поля «Порт» и «Причал». Хотим ещё «Терминал».','Терминал вместо порта?','Ничего не заменяем, добавляем третье поле.','Причал оставить?','Обязательно.','Напишем сокращённо?','Названия полностью, буква в букву.','Что ещё изменить?','Ничего. Опиши итоговый набор.'],'Сохранить поля «Порт» и «Причал», добавить отдельное поле «Терминал». Названия не сокращать, других изменений не выполнять.','Поля расположения',literals=['Порт','Причал','Терминал'])
add('code-versus-item',['Код для выдачи бейджа живёт 235 секунд; одним кодом пользуются один раз.','Сократить до 90?','Срок не меняем.','Запретить человеку получать другой бейдж когда-либо?','Нет, речь лишь о повторном применении этого кода.','Применить код при входе?','Вход — другой процесс, туда этот код не добавляй.','Какая задача нужна?','Про код выдачи, его срок и однократность.'],'Использовать код выдачи бейджа со сроком действия 235 секунд. Повторное применение этого кода запрещено; это не запрещает получение другого бейджа с новым кодом. Для входа код не использовать.','Код выдачи бейджа')
add('duration-open',['Код подтверждает приём контейнера, срабатывает однократно. Длительность ещё решаем.','Подойдёт 80 секунд?','Я не утвердил это число.','Тогда без ограничения времени?','Такого решения тоже нет.','Это код для входа?','Нет, только для приёма контейнера.','Что оставить вопросом?','Срок. Остальное уже согласовано, оформи.'],'Использовать одноразовый код подтверждения приёма контейнера, не применять его для входа. Срок действия не согласован.','Код приёма контейнера',['Какой срок действия кода установить?'])
add('exact-caption',['В списке подпись «Объём_RU-0042», файл volume_042.tsv.','Уберём ведущие нули?','Нет, всё исходное написание сохраняется.','Сделать подпись строчными буквами?','Тоже нет.','Переименовать файл?','Оставь как был.','Что включить в задачу?','Оба точных имени и запрет нормализации.'],'Сохранить подпись «Объём_RU-0042» и имя файла volume_042.tsv посимвольно, без изменения регистра, нулей или нормализации.','Исходные имена',literals=['Объём_RU-0042','volume_042.tsv'])
add('display-only',['На экране вместо asset_token выводить lease_token.','Удалять старый столбец?','Структура хранилища остаётся нетронутой.','Добавить новое рядом со старым?','Нет, старое на экране больше не показывать.','Перенести значения?','Перенос и миграция запрещены.','Итог?','Меняется лишь отображение. Запиши границы.'],'На экране показывать только lease_token вместо asset_token. Структуру хранилища не менять, перенос значений и миграцию не выполнять.','Поле экрана')
add('quoted-instruction',['В учебном тексте оставь цитату «не отправляй архив». Сам текст можно выслать преподавателю.','Цитата запрещает высылать текст?','Нет, это пример внутри него.','Тогда пример удалить?','Он нужен целиком.','Есть запрет для преподавателя?','Нет, пересылку текста ему разрешаю.','Как зафиксировать?','Оба решения, не смешивая цитату с действием.'],'Сохранить в учебном тексте цитату «не отправляй архив» целиком. Текст разрешено выслать преподавателю; цитата не запрещает эту отправку.','Учебный текст')
