add('rename-withdrawn',['Раздел «Сбор-09» планировали назвать «Приём-09», значок сделать фиолетовым, ссылку оставить.','Всё выполнять?','Переименование исключи.','Фиолетовый тоже отменяется?','Цвет остаётся в плане.','Ссылку изменить?','Её не трогать.','Что назвать в задаче?','Точное действующее имя раздела и оставшиеся изменения.'],'Сохранить имя раздела «Сбор-09», не переименовывать в «Приём-09». Значок сделать фиолетовым, ссылку сохранить.','Раздел сбора',literals=['Сбор-09'])
assert len(rows)==16
(R/'fresh-drafts.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
checks=[]
for i,n in enumerate([-97,-42,17,69,108]):
    for kind in ['equal','lower','upper','open']:
        state={'status':'open' if kind=='open' else 'final','lower':n if kind in ['equal','lower'] else None,'upper':n if kind in ['equal','upper'] else None,'lowerInclusive':True if kind=='equal' else False if kind=='lower' else None,'upperInclusive':True if kind in ['equal','upper'] else None}
        text={'equal':f'Согласовано единственное значение: {n}. Других значений не принимаем.','lower':f'Утверждён порог {n}: сам порог не подходит, подходят только значения выше.','upper':f'Согласовали максимум {n}, причём сам максимум допустим. Нижнего ограничения нет.','open':f'Число {n} прозвучало как предложение. Его не утвердили, решение пока отсутствует.'}[kind]
        checks.append({'id':f'fresh-bound-{i}-{kind}','task':'bounds','messages':[{'role':'system','content':systems['bounds']},{'role':'user','content':text},{'role':'assistant','content':json.dumps(state)}]})
for i,values in enumerate([[-89,-23,-46,-23],[-107,-8,-59,-8,-32],[-71,-15,-48,-15],[-3,-29,-116,-29],[-82,-34,-11,-34,-11],[-98,-26,-67,-26]]):
    for reverse in [False,True]:
        for style in [0,1]:
            seq=', '.join(map(str,values));words='от наибольшего к наименьшему' if reverse else 'от наименьшего к наибольшему'
            text=f'Упорядочь числа {seq} {words}. Все повторы нужны. Верни JSON-массив.' if style==0 else f'Даны [{seq}]. Итог требуется {words}, без изменения числа элементов. Ответ только массив JSON.'
            checks.append({'id':f'fresh-sort-{i}-{int(reverse)}-{style}','task':'general','messages':[{'role':'user','content':text},{'role':'assistant','content':json.dumps(sorted(values,reverse=reverse))}]})
for i,(text,answer) in enumerate([('Ответь числом: сколько секунд в двух минутах?',120),('Только число: произведение 14 и 9.',126),('Сколько сторон у квадрата? Только число.',4),('Только число: сколько часов в двух сутках?',48)]):
    checks.append({'id':f'fresh-general-{i}','task':'general','messages':[{'role':'user','content':text},{'role':'assistant','content':json.dumps(answer)}]})
assert len(checks)==48
(R/'check.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in checks))
print('Authored 16 five-user-turn drafts and 48 numeric/sort/general holdout cases.')
